// Page Table Entry (PTE) structure for memory protection
struct PTE {
    uintptr_t physical_page_addr : 52;
    bool present     : 1; // Robustness: Handles swapped pages (Page Fault)
    bool writable    : 1; // Protection: R/W access control
    bool executable  : 1; // Protection: Non-Executable (NX) bit
    bool user_mode   : 1; // Isolation: Kernel vs User memory access
    // ...
};

// --- Process Isolation via Context Switching ---

// Hardware Register pointing to the active address space root
volatile uint64_t PTBR_REGISTER; // Page Table Base Register (e.g., x86 CR3)

typedef struct {
    uint64_t virtual_map_root;
    // ... process state
} ProcessControlBlock;

// Mechanism guaranteeing isolation during task switch
void switch_process_context(ProcessControlBlock *next_p) {
    // 1. Change the active address space pointer
    PTBR_REGISTER = next_p->virtual_map_root;

    // 2. Flush Translation Lookaside Buffer (TLB)
    // (Prevents accessing the previous process's stale translations)
    asm("invlpg_or_flush_tlb"); 
}
